    """
    Implementing a recursive pattern matching algorithm with backtracking.
    Supports literal characters, '.' for any character, '*' for zero or more of the preceding element,
    and '+' for one or more of the preceding element.
    """

    def is_match(p_index: int, t_index: int) -> bool:
        # If we've reached the end of the pattern
        if p_index == len(pattern):
            return t_index == len(text)

        # Check if the current characters match or we have a '.' in pattern
        first_match = (t_index < len(text) and
                       (pattern[p_index] == text[t_index] or pattern[p_index] == '.'))

        # Handle '*' operator
        if p_index + 1 < len(pattern) and pattern[p_index + 1] == '*':
            return (is_match(p_index + 2, t_index) or
                    (first_match and is_match(p_index, t_index + 1)))

        # Handle '+' operator
        elif p_index + 1 < len(pattern) and pattern[p_index + 1] == '+':
            return (first_match and (is_match(p_index, t_index + 1) or
                                     is_match(p_index + 2, t_index)))

        # If the current characters match, proceed to the next character in both pattern and text
        return first_match and is_match(p_index + 1, t_index + 1)

    return is_match(0, 0)

